-- Private verified identity/proof extensions; source only, not PG-executed.
SET ROLE c1_table_owner;
ALTER TABLE c1_private.identities ALTER COLUMN canonical_email DROP NOT NULL;
ALTER TABLE c1_private.identities ADD CONSTRAINT identity_representation CHECK(canonical_email IS NOT NULL OR subject~'^[0-9a-f]{64}$');
CREATE TABLE c1_private.verified_identity_subjects(ns text,subject text,environment_id text NOT NULL,issuer text NOT NULL,email_key c1_private.digest32 NOT NULL,expires_at bigint NOT NULL,identity_revision bigint NOT NULL,evidence_digest c1_private.digest32 NOT NULL,PRIMARY KEY(ns,subject),FOREIGN KEY(ns,subject) REFERENCES c1_private.identities(ns,subject));
CREATE TABLE c1_private.external_session_expiry(ns text,hash c1_private.digest32,expires_at bigint NOT NULL,PRIMARY KEY(ns,hash),FOREIGN KEY(ns,hash) REFERENCES c1_private.sessions(ns,hash));
CREATE TABLE c1_private.owner_wallet_challenges(ns text,id text,subject text NOT NULL,session_hash c1_private.digest32 NOT NULL,identity_revision bigint NOT NULL,credential_epoch bigint NOT NULL,candidate text NOT NULL,kind text NOT NULL,typed_data jsonb NOT NULL,deadline bigint NOT NULL,payload jsonb NOT NULL,consumed boolean NOT NULL DEFAULT false,PRIMARY KEY(ns,id),FOREIGN KEY(ns,subject) REFERENCES c1_private.identities(ns,subject));
RESET ROLE;
GRANT SELECT,INSERT,UPDATE ON c1_private.verified_identity_subjects,c1_private.external_session_expiry,c1_private.owner_wallet_challenges TO c1_api_code_owner,c1_auth_code_owner;
CREATE OR REPLACE FUNCTION c1_api.security_reserve(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;pre c1_private.pre_sessions;i c1_private.identities;v c1_private.vouchers;u c1_private.units;old c1_private.security_mutations;m uuid=(q->>'mutation_id')::uuid;k text=q->>'kind';ex jsonb='{}';p jsonb=q->'command';dg text;ob text;b jsonb;BEGIN
 d=c1_private.guard(n);IF (SELECT security_pending FROM c1_private.transaction_guard WHERE ns=n) IS NOT NULL THEN PERFORM c1_private.fail('FENCE_PENDING');END IF;
 IF k IN('identity','grant','payer','restore') AND NOT coalesce((q->>'fixture')::boolean,false) THEN PERFORM c1_private.fail('FORBIDDEN');END IF;
 IF k IN('external_login','owner_binding') THEN
 IF NOT coalesce((q->>'private_identity')::boolean,false) THEN PERFORM c1_private.fail('FORBIDDEN');END IF;
 IF k='external_login' THEN
  IF p->>'subject_hash'!~'^[0-9a-f]{64}$' OR p->>'email_key'!~'^[0-9a-f]{64}$' OR (p->>'expires_at')::bigint<=d.now THEN PERFORM c1_private.fail('UNVERIFIED_IDENTITY');END IF;
  SELECT * INTO pre FROM c1_private.pre_sessions WHERE ns=n AND hash=c1_private.h(p->>'pre_hash');IF NOT FOUND OR pre.used OR pre.expires<=d.now OR pre.csrf IS DISTINCT FROM c1_private.h(p->>'csrf_hash') THEN PERFORM c1_private.fail('CSRF');END IF;
  SELECT * INTO i FROM c1_private.identities WHERE ns=n AND subject=p->>'subject_hash';
  ex=jsonb_build_object('subject',p->>'subject_hash','identity_revision',coalesce(i.revision,0));ob='identity:'||(p->>'subject_hash');
 ELSE
  s=c1_private.auth(n,p,true);IF NOT EXISTS(SELECT 1 FROM c1_private.verified_identity_subjects WHERE ns=n AND subject=s.subject AND identity_revision=s.identity_revision AND expires_at>d.now) THEN PERFORM c1_private.fail('REAL_IDENTITY_BINDING_REQUIRED');END IF;
  IF NOT EXISTS(SELECT 1 FROM c1_private.owner_wallet_challenges WHERE ns=n AND id=p->>'challenge_id' AND subject=s.subject AND session_hash=s.hash AND identity_revision=s.identity_revision AND credential_epoch=d.credential_epoch AND NOT consumed AND deadline>d.now AND candidate=p->>'owner' AND kind=p->>'owner_kind' AND payload=p->'expected_challenge') THEN PERFORM c1_private.fail('INVALID_WALLET_PROOF');END IF;
  ex=jsonb_build_object('subject',s.subject,'identity_revision',s.identity_revision,'session_revision',s.revision,'session_hash',encode(s.hash,'hex'),'owner_revision',coalesce((SELECT revision FROM c1_private.verified_owner_bindings WHERE ns=n AND subject=s.subject),0));ob='owner:'||s.subject;
 END IF;
 ELSIF k='login' THEN SELECT * INTO pre FROM c1_private.pre_sessions WHERE ns=n AND hash=c1_private.h(p->>'pre_hash');IF NOT FOUND OR pre.used OR pre.expires<=d.now OR pre.csrf<>c1_private.h(p->>'csrf_hash') THEN PERFORM c1_private.fail('CSRF');END IF;SELECT * INTO i FROM c1_private.identities WHERE ns=n AND subject=(SELECT subject FROM c1_private.assertions WHERE ns=n AND hash=c1_private.h(p->>'assertion_hash') AND NOT used AND expires>d.now AND audience='mcpay-c1' AND environment='local-synthetic');IF NOT FOUND THEN PERFORM c1_private.fail('INVALID_ASSERTION');END IF;ex=jsonb_build_object('subject',i.subject,'identity_revision',i.revision);ob='identity:'||i.subject;
 ELSIF k IN('logout','reauth','recover','display','lock') THEN s=c1_private.auth(n,p,true);ex=jsonb_build_object('session_hash',encode(s.hash,'hex'),'session_revision',s.revision,'identity_revision',s.identity_revision,'subject',s.subject);ob='session:'||encode(s.hash,'hex');IF k='lock' THEN PERFORM c1_private.owner_auth(n,s,p->>'store','redeem');END IF;
 IF k='reauth' THEN SELECT * INTO i FROM c1_private.identities WHERE ns=n AND subject=s.subject;IF NOT EXISTS(SELECT 1 FROM c1_private.assertions WHERE ns=n AND hash=c1_private.h(p->>'assertion_hash') AND subject=s.subject AND NOT used AND expires>d.now AND audience='mcpay-c1' AND environment='local-synthetic') THEN PERFORM c1_private.fail('INVALID_ASSERTION');END IF;END IF;
 IF k IN('recover','display') THEN v=c1_private.voucher_auth(n,s,p->>'voucher');IF p ? 'key' THEN SELECT * INTO old FROM c1_private.security_mutations WHERE ns=n AND kind=k AND command->>'key'=p->>'key' AND command->>'voucher'=p->>'voucher' AND expected->>'subject'=s.subject AND state='COMMITTED';IF FOUND THEN IF k='display' AND old.command->>'access_hash' IS DISTINCT FROM p->>'access_hash' THEN PERFORM c1_private.fail('CONFLICT');END IF;RETURN jsonb_build_object('replay',true,'mutation_id',old.id,'result',old.result);END IF;END IF;SELECT * INTO u FROM c1_private.units WHERE ns=n AND store=v.store AND seq=v.seq;IF k='recover' AND d.now-s.authenticated>900 THEN PERFORM c1_private.fail('REAUTH_REQUIRED');END IF;IF k='display' THEN PERFORM c1_private.guard(n,true);IF NOT c1_private.content_available(n,u.store,u.meal,u.version) THEN PERFORM c1_private.fail('CONTENT_UNAVAILABLE');END IF;IF NOT EXISTS(SELECT 1 FROM c1_private.access_credentials WHERE ns=n AND voucher=v.id AND hash=c1_private.h(p->>'access_hash') AND session_hash=s.hash AND epoch=v.access_epoch AND credential_epoch=d.credential_epoch AND active) THEN PERFORM c1_private.fail('OLD_ACCESS');END IF;IF u.bucket<>'R' OR u.generation<>v.generation OR u.lock_id IS NOT NULL OR u.active_op IS NOT NULL OR d.now>=v.expires_at OR c1_private.window_end((SELECT windows FROM c1_private.terms WHERE ns=n AND store=u.store AND meal=u.meal AND version=u.version),d.now)=0 THEN PERFORM c1_private.fail('NOT_REDEEMABLE');END IF;END IF;ex=ex||jsonb_build_object('voucher',v.id,'access_epoch',v.access_epoch,'display_epoch',v.display_epoch);ob='voucher:'||v.id;END IF;
 ELSIF k IN('identity','grant','payer') THEN SELECT * INTO i FROM c1_private.identities WHERE ns=n AND subject=p->>'subject';IF NOT FOUND THEN PERFORM c1_private.fail('NOT_FOUND');END IF;ex=jsonb_build_object('subject',i.subject,'identity_revision',i.revision);ob=k||':'||i.subject||':'||coalesce(p->>'store','');IF k='grant' THEN ex=ex||jsonb_build_object('grant_revision',(SELECT max(revision) FROM c1_private.grants WHERE ns=n AND subject=i.subject AND store=p->>'store'));ELSIF k='payer' THEN ex=ex||jsonb_build_object('payer_revision',(SELECT revision FROM c1_private.payer_bindings WHERE ns=n AND subject=i.subject));END IF;
 ELSIF k='restore' THEN ex=jsonb_build_object('restore_generation',d.restore_generation);ob='restore'; ELSE PERFORM c1_private.fail('UNSUPPORTED_SECURITY_KIND');END IF;

 dg=encode(sha256(convert_to(jsonb_build_object('kind',k,'command',p,'expected',ex)::text,'UTF8')),'hex');
 INSERT INTO c1_private.security_mutations(ns,id,kind,command,expected,command_digest,state) VALUES(n,m,k,p,ex,dg,'RESERVED');UPDATE c1_private.transaction_guard SET security_pending=m WHERE ns=n;
 b=jsonb_build_object('mutation_id',m,'kind',k,'object_id',ob,'expected_revision',ex,'command_digest',dg,'restore_generation',CASE WHEN k='restore' THEN d.restore_generation+1 ELSE d.restore_generation END,'source_epoch',d.source_epoch,'deployment_generation',1,'credential_epoch',CASE WHEN k='restore' THEN greatest(d.credential_epoch+1,coalesce((q->'retained_epochs'->>'credential_epoch')::bigint,0)+1) ELSE d.credential_epoch END,'authority_checkpoint',coalesce(q->'authority_evidence'->>'parent',d.parent),'authority_highwater',coalesce((q->'authority_evidence'->>'height')::bigint,d.height),'floors',coalesce(q->'retained_floors','{}'::jsonb),'command',jsonb_build_object('kind',k,'digest',dg));UPDATE c1_private.security_mutations SET binding=b WHERE ns=n AND id=m;RETURN b;END $$;

CREATE OR REPLACE FUNCTION c1_api.security_apply(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;m c1_private.security_mutations;p jsonb;s c1_private.sessions;i c1_private.identities;v c1_private.vouchers;u c1_private.units;res jsonb='{}';floors jsonb='{}';we bigint;redeem boolean;BEGIN
 d=c1_private.guard(n,false,(q->>'mutation_id')::uuid);SELECT * INTO m FROM c1_private.security_mutations WHERE ns=n AND id=(q->>'mutation_id')::uuid FOR UPDATE;IF NOT FOUND OR m.state<>'PREPARED' OR m.sequence<>(q->>'sequence')::bigint OR m.digest<>q->>'digest' OR (SELECT security_pending FROM c1_private.transaction_guard WHERE ns=n) IS DISTINCT FROM m.id THEN PERFORM c1_private.fail('STALE_PREPARE');END IF;p=m.command;
 IF m.kind IN('logout','reauth','recover','display','lock') THEN s=c1_private.auth(n,p,true);IF s.revision<>(m.expected->>'session_revision')::bigint THEN PERFORM c1_private.fail('STALE_PREPARE');END IF;END IF;
 IF m.kind='external_login' THEN
  SELECT * INTO i FROM c1_private.identities WHERE ns=n AND subject=p->>'subject_hash';
  IF coalesce(i.revision,0)<>(m.expected->>'identity_revision')::bigint OR (p->>'expires_at')::bigint<=d.now THEN PERFORM c1_private.fail('STALE_PREPARE');END IF;
  UPDATE c1_private.pre_sessions SET used=true WHERE ns=n AND hash=c1_private.h(p->>'pre_hash') AND NOT used AND expires>d.now AND csrf=c1_private.h(p->>'csrf_hash');IF NOT FOUND THEN PERFORM c1_private.fail('CSRF');END IF;
  INSERT INTO c1_private.identities(ns,subject,canonical_email,email_key) VALUES(n,p->>'subject_hash',NULL,c1_private.h(p->>'email_key')) ON CONFLICT(ns,subject) DO UPDATE SET email_key=EXCLUDED.email_key,revision=c1_private.identities.revision+CASE WHEN c1_private.identities.email_key IS DISTINCT FROM EXCLUDED.email_key THEN 1 ELSE 0 END RETURNING * INTO i;
  INSERT INTO c1_private.verified_identity_subjects VALUES(n,i.subject,p->>'environment_id',p->>'issuer',i.email_key,(p->>'expires_at')::bigint,i.revision,c1_private.h(p->>'evidence_digest')) ON CONFLICT(ns,subject) DO UPDATE SET email_key=EXCLUDED.email_key,expires_at=EXCLUDED.expires_at,identity_revision=EXCLUDED.identity_revision,evidence_digest=EXCLUDED.evidence_digest WHERE c1_private.verified_identity_subjects.environment_id=EXCLUDED.environment_id AND c1_private.verified_identity_subjects.issuer=EXCLUDED.issuer;
  IF NOT FOUND THEN PERFORM c1_private.fail('IDENTITY_PROFILE_CONFLICT');END IF;
  UPDATE c1_private.sessions SET revoked=true,revision=revision+1 WHERE ns=n AND subject=i.subject AND NOT revoked;
  INSERT INTO c1_private.sessions(ns,hash,csrf,subject,identity_revision,epoch,created,activity,authenticated) VALUES(n,c1_private.h(p->>'new_session_hash'),c1_private.h(p->>'new_csrf_hash'),i.subject,i.revision,d.credential_epoch,d.now,d.now,d.now);
  INSERT INTO c1_private.external_session_expiry VALUES(n,c1_private.h(p->>'new_session_hash'),least((p->>'expires_at')::bigint,d.now+86400));
  res=jsonb_build_object('authenticated',true,'expiresAt',least((p->>'expires_at')::bigint,d.now+86400));floors=jsonb_build_object('identity:'||i.subject,i.revision,'credential',d.credential_epoch,'session:'||(p->>'new_session_hash'),1);
 ELSIF m.kind='owner_binding' THEN
  s=c1_private.auth(n,p,true);IF s.revision<>(m.expected->>'session_revision')::bigint OR s.identity_revision<>(m.expected->>'identity_revision')::bigint OR coalesce((SELECT revision FROM c1_private.verified_owner_bindings WHERE ns=n AND subject=s.subject),0)<>(m.expected->>'owner_revision')::bigint THEN PERFORM c1_private.fail('STALE_PREPARE');END IF;
  UPDATE c1_private.owner_wallet_challenges SET consumed=true WHERE ns=n AND id=p->>'challenge_id' AND subject=s.subject AND session_hash=s.hash AND identity_revision=s.identity_revision AND credential_epoch=d.credential_epoch AND NOT consumed AND deadline>d.now AND candidate=p->>'owner' AND kind=p->>'owner_kind' AND payload=p->'expected_challenge';IF NOT FOUND THEN PERFORM c1_private.fail('INVALID_WALLET_PROOF');END IF;
  INSERT INTO c1_private.verified_owner_bindings VALUES(n,s.subject,p->>'owner',(m.expected->>'owner_revision')::bigint+1,true,'VERIFIED_EXTERNAL',p->>'owner_kind',(SELECT evidence_digest FROM c1_private.verified_identity_subjects WHERE ns=n AND subject=s.subject),c1_private.h(p->>'proof_digest'),s.identity_revision,d.credential_epoch,(SELECT expires_at FROM c1_private.verified_identity_subjects WHERE ns=n AND subject=s.subject)) ON CONFLICT(ns,subject) DO UPDATE SET owner=EXCLUDED.owner,revision=EXCLUDED.revision,enabled=true,owner_kind=EXCLUDED.owner_kind,wallet_evidence=EXCLUDED.wallet_evidence,identity_revision=EXCLUDED.identity_revision,credential_epoch=EXCLUDED.credential_epoch,verified_until=EXCLUDED.verified_until;
  INSERT INTO c1_private.payer_bindings VALUES(n,s.subject,p->>'owner',1,true) ON CONFLICT(ns,subject) DO UPDATE SET address=EXCLUDED.address,revision=c1_private.payer_bindings.revision+1,enabled=true;
  res=jsonb_build_object('walletBound',true,'owner',p->>'owner','bindingRevision',(m.expected->>'owner_revision')::bigint+1);floors=jsonb_build_object('owner:'||s.subject,(m.expected->>'owner_revision')::bigint+1,'payer:'||s.subject,(SELECT revision FROM c1_private.payer_bindings WHERE ns=n AND subject=s.subject));
 ELSIF m.kind IN('login','reauth') THEN SELECT * INTO i FROM c1_private.identities WHERE ns=n AND subject=m.expected->>'subject';IF i.revision<>(m.expected->>'identity_revision')::bigint THEN PERFORM c1_private.fail('STALE_PREPARE');END IF;UPDATE c1_private.assertions SET used=true WHERE ns=n AND hash=c1_private.h(p->>'assertion_hash') AND NOT used AND expires>d.now;IF NOT FOUND THEN PERFORM c1_private.fail('INVALID_ASSERTION');END IF;IF m.kind='login' THEN UPDATE c1_private.pre_sessions SET used=true WHERE ns=n AND hash=c1_private.h(p->>'pre_hash') AND NOT used AND expires>d.now;IF NOT FOUND THEN PERFORM c1_private.fail('CSRF');END IF;ELSE UPDATE c1_private.sessions SET revoked=true,revision=revision+1 WHERE ns=n AND hash=s.hash;UPDATE c1_private.access_credentials SET active=false WHERE ns=n AND session_hash=s.hash;UPDATE c1_private.display_credentials SET active=false WHERE ns=n AND session_hash=s.hash;END IF;
 INSERT INTO c1_private.sessions(ns,hash,csrf,subject,identity_revision,epoch,created,activity,authenticated) VALUES(n,c1_private.h(p->>'new_session_hash'),c1_private.h(p->>'new_csrf_hash'),i.subject,i.revision,d.credential_epoch,d.now,d.now,d.now);res=jsonb_build_object('authenticated',true,'expiresAt',d.now+86400);floors=jsonb_build_object('identity:'||i.subject,i.revision,'credential',d.credential_epoch);IF m.kind='reauth' THEN floors=floors||jsonb_build_object('session:'||encode(s.hash,'hex'),s.revision+1);END IF;
 ELSIF m.kind='logout' THEN UPDATE c1_private.sessions SET revoked=true,revision=revision+1 WHERE ns=n AND hash=s.hash;UPDATE c1_private.access_credentials SET active=false WHERE ns=n AND session_hash=s.hash;UPDATE c1_private.display_credentials SET active=false WHERE ns=n AND session_hash=s.hash;res=jsonb_build_object('loggedOut',true);floors=jsonb_build_object('session:'||encode(s.hash,'hex'),s.revision+1);
 ELSIF m.kind IN('recover','display') THEN v=c1_private.voucher_auth(n,s,p->>'voucher');IF v.access_epoch<>(m.expected->>'access_epoch')::bigint OR v.display_epoch<>(m.expected->>'display_epoch')::bigint THEN PERFORM c1_private.fail('STALE_PREPARE');END IF;SELECT * INTO u FROM c1_private.units WHERE ns=n AND store=v.store AND seq=v.seq;redeem=c1_private.content_available(n,u.store,u.meal,u.version) AND u.bucket='R' AND u.generation=v.generation AND u.lock_id IS NULL AND u.active_op IS NULL AND d.now<v.expires_at AND NOT d.halt AND d.now-d.heartbeat<=30;
 IF m.kind='recover' THEN UPDATE c1_private.access_credentials SET active=false WHERE ns=n AND voucher=v.id;UPDATE c1_private.display_credentials SET active=false WHERE ns=n AND voucher=v.id;UPDATE c1_private.vouchers SET access_epoch=access_epoch+1,display_epoch=display_epoch+1 WHERE ns=n AND id=v.id RETURNING * INTO v;IF redeem THEN INSERT INTO c1_private.access_credentials VALUES(n,v.id,c1_private.h(p->>'new_access_hash'),s.hash,v.access_epoch,d.credential_epoch,true);END IF;
 -- Recovery rotates requesting session and CSRF, preserving original authenticatedAt.
 UPDATE c1_private.sessions SET revoked=true,revision=revision+1 WHERE ns=n AND hash=s.hash;INSERT INTO c1_private.sessions(ns,hash,csrf,subject,identity_revision,epoch,created,activity,authenticated) VALUES(n,c1_private.h(p->>'new_session_hash'),c1_private.h(p->>'new_csrf_hash'),s.subject,s.identity_revision,d.credential_epoch,s.created,d.now,s.authenticated);INSERT INTO c1_private.external_session_expiry SELECT n,c1_private.h(p->>'new_session_hash'),expires_at FROM c1_private.external_session_expiry WHERE ns=n AND hash=s.hash;UPDATE c1_private.access_credentials SET session_hash=c1_private.h(p->>'new_session_hash') WHERE ns=n AND voucher=v.id AND active;res=jsonb_build_object('id',v.id,'accessEpoch',v.access_epoch,'redeemable',redeem);
 ELSE IF NOT redeem THEN PERFORM c1_private.fail('NOT_REDEEMABLE');END IF;SELECT c1_private.window_end(windows,d.now) INTO we FROM c1_private.terms WHERE ns=n AND store=u.store AND meal=u.meal AND version=u.version;IF we=0 THEN PERFORM c1_private.fail('OUTSIDE_WINDOW');END IF;UPDATE c1_private.display_credentials SET active=false WHERE ns=n AND voucher=v.id;UPDATE c1_private.vouchers SET display_epoch=display_epoch+1 WHERE ns=n AND id=v.id RETURNING * INTO v;INSERT INTO c1_private.display_credentials VALUES(n,v.id,c1_private.h(p->>'new_display_hash'),s.hash,v.access_epoch,v.display_epoch,d.credential_epoch,least(d.now+120,v.expires_at,we),true);res=jsonb_build_object('id',v.id,'displayEpoch',v.display_epoch,'validUntil',least(d.now+120,v.expires_at,we));END IF;floors=jsonb_build_object('access:'||v.id,v.access_epoch,'display:'||v.id,v.display_epoch,'session:'||encode(s.hash,'hex'),CASE WHEN m.kind='recover' THEN s.revision+1 ELSE s.revision END);
 ELSIF m.kind='lock' THEN res=c1_api.lock_confirm(n,p||jsonb_build_object('mutation_id',m.id));floors=(SELECT jsonb_build_object('access:'||vc.id,vc.access_epoch,'display:'||vc.id,vc.display_epoch) FROM c1_private.vouchers vc WHERE vc.ns=n AND vc.id=(SELECT voucher_id FROM c1_private.units WHERE ns=n AND active_op=(res->>'id')::uuid));
 ELSIF m.kind='identity' THEN UPDATE c1_private.identities SET canonical_email=p->>'canonical_email',email_key=c1_private.h(p->>'email_key'),revision=revision+1 WHERE ns=n AND subject=p->>'subject' AND revision=(m.expected->>'identity_revision')::bigint RETURNING * INTO i;IF NOT FOUND THEN PERFORM c1_private.fail('STALE_PREPARE');END IF;UPDATE c1_private.sessions SET revoked=true,revision=revision+1 WHERE ns=n AND subject=i.subject;UPDATE c1_private.access_credentials SET active=false WHERE ns=n AND session_hash IN(SELECT hash FROM c1_private.sessions WHERE ns=n AND subject=i.subject);UPDATE c1_private.display_credentials SET active=false WHERE ns=n AND session_hash IN(SELECT hash FROM c1_private.sessions WHERE ns=n AND subject=i.subject);res=jsonb_build_object('revision',i.revision);floors=jsonb_build_object('identity:'||i.subject,i.revision);
 ELSIF m.kind='grant' THEN IF (SELECT max(revision) FROM c1_private.grants WHERE ns=n AND subject=p->>'subject' AND store=p->>'store') IS DISTINCT FROM (m.expected->>'grant_revision')::bigint THEN PERFORM c1_private.fail('STALE_PREPARE');END IF;UPDATE c1_private.grants SET enabled=coalesce((p->>'enabled')::boolean,false),revision=revision+1 WHERE ns=n AND subject=p->>'subject' AND store=p->>'store' ;res=(SELECT jsonb_build_object('revision',max(revision)) FROM c1_private.grants WHERE ns=n AND subject=p->>'subject' AND store=p->>'store');floors=jsonb_build_object('grant:'||(p->>'subject')||':'||(p->>'store'),(res->>'revision')::bigint);
 ELSIF m.kind='payer' THEN IF (SELECT revision FROM c1_private.payer_bindings WHERE ns=n AND subject=p->>'subject') IS DISTINCT FROM (m.expected->>'payer_revision')::bigint THEN PERFORM c1_private.fail('STALE_PREPARE');END IF;UPDATE c1_private.payer_bindings SET enabled=coalesce((p->>'enabled')::boolean,false),revision=revision+1 WHERE ns=n AND subject=p->>'subject' RETURNING jsonb_build_object('revision',revision) INTO res;floors=jsonb_build_object('payer:'||(p->>'subject'),(res->>'revision')::bigint);
 ELSIF m.kind='restore' THEN UPDATE c1_private.deployment SET halt=true,reason='CONTROLLED_RESTORE',restore_generation=restore_generation+1,credential_epoch=greatest(credential_epoch+1,coalesce((p->>'credential_floor')::bigint,0)+1) WHERE ns=n RETURNING jsonb_build_object('restore_generation',restore_generation,'credential_epoch',credential_epoch) INTO res;UPDATE c1_private.sessions SET revoked=true WHERE ns=n;UPDATE c1_private.access_credentials SET active=false WHERE ns=n;UPDATE c1_private.display_credentials SET active=false WHERE ns=n;floors=jsonb_build_object('credential',(res->>'credential_epoch')::bigint,'restore',(res->>'restore_generation')::bigint);
 END IF;
 INSERT INTO c1_private.security_commits VALUES(n,m.id,m.sequence,m.digest,res,floors);UPDATE c1_private.security_mutations SET state='APPLIED',result=res WHERE ns=n AND id=m.id;RETURN res;END $$;

CREATE OR REPLACE FUNCTION c1_private.auth(n text,q jsonb,mutation boolean DEFAULT false) RETURNS c1_private.sessions LANGUAGE plpgsql AS $$ DECLARE s c1_private.sessions;i c1_private.identities;d c1_private.deployment;BEGIN IF q->>'session_hash' IS NULL THEN PERFORM c1_private.fail('UNAUTHENTICATED');END IF;SELECT * INTO d FROM c1_private.deployment WHERE ns=n; SELECT * INTO s FROM c1_private.sessions WHERE ns=n AND hash=c1_private.h(q->>'session_hash');IF NOT FOUND THEN PERFORM c1_private.fail('UNAUTHENTICATED');END IF; SELECT * INTO i FROM c1_private.identities WHERE ns=n AND subject=s.subject;IF s.revoked OR s.epoch<>d.credential_epoch OR s.identity_revision<>i.revision OR d.now>=s.created+86400 OR d.now>=s.activity+1800 THEN PERFORM c1_private.fail('UNAUTHENTICATED');END IF;IF i.canonical_email IS NULL AND (NOT EXISTS(SELECT 1 FROM c1_private.verified_identity_subjects WHERE ns=n AND subject=s.subject AND identity_revision=i.revision AND email_key=i.email_key) OR NOT EXISTS(SELECT 1 FROM c1_private.external_session_expiry WHERE ns=n AND hash=s.hash AND expires_at>d.now)) THEN PERFORM c1_private.fail('UNAUTHENTICATED');END IF;IF mutation AND (q->>'csrf_hash' IS NULL OR s.csrf IS DISTINCT FROM c1_private.h(q->>'csrf_hash')) THEN PERFORM c1_private.fail('CSRF');END IF;RETURN s;END $$;

CREATE OR REPLACE FUNCTION c1_api.security_startup(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE dom text;ob jsonb;k text;v jsonb;actual bigint;d c1_private.deployment;BEGIN d=c1_private.guard(n);IF coalesce((q->>'namespace_probe')::boolean,false) THEN RETURN jsonb_build_object('exists',true,'matched',false);END IF;IF d.source_epoch<>coalesce((q->'epochs'->>'source_epoch')::bigint,d.source_epoch) OR d.credential_epoch<>coalesce((q->'epochs'->>'credential_epoch')::bigint,d.credential_epoch) OR d.restore_generation<>coalesce((q->'epochs'->>'restore_generation')::bigint,d.restore_generation) THEN RETURN jsonb_build_object('matched',false,'reason','EPOCH_MISMATCH');END IF;IF (SELECT security_pending FROM c1_private.transaction_guard WHERE ns=n) IS NOT NULL OR (SELECT execution_pending FROM c1_private.transaction_guard WHERE ns=n) IS NOT NULL THEN RETURN jsonb_build_object('matched',false,'reason','PENDING');END IF;
 FOR dom,ob IN SELECT key,value FROM jsonb_each(coalesce(q->'floors','{}')) LOOP IF dom='execution' THEN CONTINUE;END IF;FOR k,v IN SELECT key,value FROM jsonb_each(ob) LOOP actual=NULL;
 IF dom='credential' THEN actual=d.credential_epoch;ELSIF dom='restore' THEN actual=d.restore_generation;ELSIF dom='identity' THEN SELECT revision INTO actual FROM c1_private.identities WHERE ns=n AND subject=k;ELSIF dom='session' THEN SELECT revision INTO actual FROM c1_private.sessions WHERE ns=n AND hash=decode(k,'hex');ELSIF dom='access' THEN SELECT access_epoch INTO actual FROM c1_private.vouchers WHERE ns=n AND id=k;ELSIF dom='display' THEN SELECT display_epoch INTO actual FROM c1_private.vouchers WHERE ns=n AND id=k;ELSIF dom='grant' THEN SELECT max(revision) INTO actual FROM c1_private.grants WHERE ns=n AND subject=split_part(k,':',1) AND store=split_part(k,':',2);ELSIF dom='owner' THEN SELECT revision INTO actual FROM c1_private.verified_owner_bindings WHERE ns=n AND subject=k;ELSIF dom='payer' THEN SELECT revision INTO actual FROM c1_private.payer_bindings WHERE ns=n AND subject=k;END IF;
 IF actual IS NULL OR actual<v::text::bigint THEN UPDATE c1_private.deployment SET halt=true,reason='JOURNAL_FLOOR' WHERE ns=n;RETURN jsonb_build_object('matched',false,'reason','FLOOR');END IF;END LOOP;END LOOP;RETURN jsonb_build_object('matched',true);END $$;
REVOKE ALL ON FUNCTION c1_private.auth(text,jsonb,boolean) FROM PUBLIC;

CREATE FUNCTION c1_onboarding_internal.wallet_session(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$
DECLARE s c1_private.sessions;i c1_private.verified_identity_subjects;expires bigint;BEGIN s=c1_private.auth(n,q,true);SELECT * INTO i FROM c1_private.verified_identity_subjects WHERE ns=n AND subject=s.subject AND identity_revision=s.identity_revision;SELECT expires_at INTO expires FROM c1_private.external_session_expiry WHERE ns=n AND hash=s.hash;IF i.subject IS NULL OR expires IS NULL THEN PERFORM c1_private.fail('REAL_IDENTITY_BINDING_REQUIRED');END IF;RETURN jsonb_build_object('identity',jsonb_build_object('environment_id',i.environment_id,'issuer',i.issuer,'subject_hash',i.subject,'email_key',encode(i.email_key,'hex'),'expires_at',i.expires_at),'expiresAt',least(expires,s.created+86400,s.activity+1800));END $$;
CREATE FUNCTION c1_onboarding_internal.wallet_challenge_create(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$
DECLARE d c1_private.deployment;s c1_private.sessions;p jsonb=q->'payload';BEGIN d=c1_private.guard(n,true);s=c1_private.auth(n,q,true);PERFORM c1_onboarding_internal.wallet_session(n,q);IF p->'session'->>'session_hash' IS DISTINCT FROM '0x'||encode(s.hash,'hex') OR p->'session'->'identity'->>'subject_hash' IS DISTINCT FROM s.subject OR (p->>'deadline')::bigint<=d.now OR (p->>'deadline')::bigint>d.now+300 THEN PERFORM c1_private.fail('INVALID_WALLET_PROOF');END IF;IF (SELECT count(*) FROM c1_private.owner_wallet_challenges WHERE ns=n AND subject=s.subject AND NOT consumed AND deadline>d.now)>=10 THEN PERFORM c1_private.fail('QUEUE_FULL');END IF;INSERT INTO c1_private.owner_wallet_challenges VALUES(n,p->>'challenge_id',s.subject,s.hash,s.identity_revision,d.credential_epoch,p->>'wallet','EOA','{}'::jsonb,(p->>'deadline')::bigint,p,false) ON CONFLICT DO NOTHING;RETURN jsonb_build_object('reserved',FOUND);END $$;
CREATE FUNCTION c1_onboarding_internal.wallet_challenge_get(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$
DECLARE s c1_private.sessions;p jsonb;BEGIN s=c1_private.auth(n,q,true);SELECT payload INTO p FROM c1_private.owner_wallet_challenges WHERE ns=n AND id=q->>'id' AND subject=s.subject AND session_hash=s.hash AND NOT consumed;RETURN jsonb_build_object('payload',p);END $$;
CREATE UNIQUE INDEX wallet_nonce_unique ON c1_private.owner_wallet_challenges(ns,(payload->>'nonce'));
REVOKE ALL ON FUNCTION c1_onboarding_internal.wallet_session(text,jsonb),c1_onboarding_internal.wallet_challenge_create(text,jsonb),c1_onboarding_internal.wallet_challenge_get(text,jsonb) FROM PUBLIC;
ALTER FUNCTION c1_onboarding_internal.wallet_session(text,jsonb) OWNER TO c1_auth_code_owner;
ALTER FUNCTION c1_onboarding_internal.wallet_challenge_create(text,jsonb) OWNER TO c1_auth_code_owner;
ALTER FUNCTION c1_onboarding_internal.wallet_challenge_get(text,jsonb) OWNER TO c1_auth_code_owner;
